import { $, i, icons, busy, toast, modal, closeModal, stat, expenseTable } from './ui.js';
import { listProfiles, listPolicies, expenses, audits, rpc } from './api.js';
import { roleNames } from './access.js';
import { escapeHTML as h, INR, sum, timeLabel, initials } from './utils.js';
import { expenseGroups, awaitingManagerAssignment } from './expense-state.js';
export async function adminPage() {
  const [profiles,policies,rows,logs]=await Promise.all([listProfiles(),listPolicies(),expenses(),audits()]);
  const {submitted,pending,paid}=expenseGroups(rows),unassigned=rows.filter(awaitingManagerAssignment);
  $('#page-content').innerHTML=`<div class="stats-grid">${stat('Organization users',String(profiles.length),'Employee and reviewer accounts','users','lavender')}${stat('Total submitted',INR(sum(submitted)),`${submitted.length} submitted claims`,'wallet','blue')}${stat('Awaiting review',String(pending.length),'Pending / flagged expenses','flag','amber')}${stat('Reimbursed amount',INR(sum(paid)),'Completed demo reimbursements','badge-check','green')}</div>${unassigned.length?`<div class="notice section-space">${i('info')}<div><strong>${unassigned.length} submitted claims need a manager.</strong> Use People &amp; permissions → Manage to assign each employee a manager. Pending claims are routed automatically.</div></div>`:''}${roleRequests(profiles)}<section class="panel section-space"><div class="panel-header"><div><h2>People & permissions</h2><p>New accounts start as employees. Review role requests or assign trusted access here.</p></div></div><div class="table-tools"><label class="search-box">${i('search')}<span class="visually-hidden">Search people</span><input id="user-search" type="search" placeholder="Name or email…"></label></div><div id="users-table"></div><div class="pagination"><span id="users-page"></span><div><button class="button secondary" id="users-prev">Previous</button><button class="button secondary" id="users-next">Next</button></div></div></section><section class="panel section-space"><div class="panel-header"><div><h2>Company expense policies</h2><p>Limits are checked by the database at submission and review time.</p></div></div><div class="policy-editor-grid">${policies.map(p=>`<form class="policy-editor" data-category="${h(p.category)}"><h3>${h(p.category)}</h3><label class="field"><span>Maximum amount (₹)</span><input name="limit" type="number" min="0.01" max="10000000" step="0.01" required value="${p.maximum_amount}"></label><label class="checkbox-label"><input name="active" type="checkbox" ${p.active?'checked':''}>Active category</label><button type="submit" class="button secondary">${i('save')}Save policy</button></form>`).join('')}</div></section><section class="panel section-space"><div class="panel-header"><div><h2>Organization expense monitor</h2><p>All claims across departments</p></div></div><div id="admin-expenses"></div></section><section class="panel"><div class="panel-header"><div><h2>Audit logs</h2><p>Read-only records of submissions, decisions and access changes</p></div></div><div id="audit-table"></div><div class="pagination"><span id="audit-page"></span><div><button class="button secondary" id="audit-prev">Previous</button><button class="button secondary" id="audit-next">Next</button></div></div></section>`;
  document.querySelectorAll('.review-role-request').forEach(button=>button.onclick=()=>{
    const person=profiles.find(p=>p.id===button.dataset.id),decision=button.dataset.decision;
    modal(decision==='approved'?'Approve workspace access':'Decline role request',`<p class="muted-note">${h(person.full_name)} requested ${h(roleNames[person.requested_role])} access. ${decision==='approved'?'Approval grants the permissions of that role.':''}</p><form id="role-review-form"><div class="field"><label for="role-review-comment">${decision==='rejected'?'Reason (required)':'Comment (optional)'}</label><textarea id="role-review-comment" maxlength="500" ${decision==='rejected'?'required minlength="5"':''} rows="3"></textarea></div><div class="modal-footer"><button type="submit" class="button ${decision==='approved'?'primary':'danger'}">${decision==='approved'?'Approve role':'Decline request'}</button></div></form>`);
    $('#role-review-form').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await rpc('review_role_request',{p_id:person.id,p_decision:decision,p_expected_role:person.requested_role,p_comment:$('#role-review-comment').value.trim()});closeModal();toast('Role request '+decision+'.');await adminPage();});};
  });
  let userPage=1,query='',auditPage=1;const pageSize=8;
  function drawUsers(){const found=profiles.filter(p=>`${p.full_name} ${p.email}`.toLowerCase().includes(query.toLowerCase()));const total=Math.max(1,Math.ceil(found.length/pageSize));userPage=Math.min(userPage,total);$('#users-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>ROLE</th><th>MANAGER</th><th>ACCESS</th></tr></thead><tbody>${found.slice((userPage-1)*pageSize,userPage*pageSize).map(p=>`<tr><td><div class="expense-name"><span class="avatar">${initials(p.full_name)}</span><div><strong>${h(p.full_name)}</strong><small>${h(p.email)}</small></div></div></td><td>${h(p.department)}</td><td><span class="category-pill">${h(p.role)}</span></td><td>${h(profiles.find(m=>m.id===p.manager_id)?.full_name||'Unassigned')}</td><td><button class="row-action edit-user" data-id="${p.id}">Manage</button></td></tr>`).join('')}</tbody></table></div>`;$('#users-page').textContent=`${found.length} users · Page ${userPage} of ${total}`;$('#users-prev').disabled=userPage<=1;$('#users-next').disabled=userPage>=total;document.querySelectorAll('.edit-user').forEach(b=>b.onclick=()=>editUser(profiles.find(p=>p.id===b.dataset.id)));icons();}
  function editUser(person){const managers=profiles.filter(p=>p.role==='manager'&&p.id!==person.id);modal('Manage user access',`<p class="muted-note">${h(person.full_name)} · ${h(person.email)}</p><form id="user-access-form" class="form-grid"><div class="field full"><label for="user-role">Role</label><select id="user-role">${['employee','manager','finance','admin'].map(r=>`<option ${r===person.role?'selected':''}>${r}</option>`).join('')}</select></div><div class="field full"><label for="user-manager">Assigned manager (employees only)</label><select id="user-manager"><option value="">Unassigned</option>${managers.map(p=>`<option value="${p.id}" ${p.id===person.manager_id?'selected':''}>${h(p.full_name)}</option>`).join('')}</select></div><div class="field full"><label for="user-department">Department</label><input id="user-department" required maxlength="100" value="${h(person.department)}"></div><p class="muted-note">Assigning a manager routes this employee’s pending claims to that manager. Completed decisions keep their original reviewer. A manager must have no assigned employees or pending reviews before their role can change. The last administrator cannot be removed.</p><div class="field full"><button class="button primary" type="submit">Save access settings</button></div></form>`);$('#user-access-form').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await rpc('admin_update_user',{p_id:person.id,p_role:$('#user-role').value,p_manager:$('#user-manager').value||null,p_department:$('#user-department').value.trim()});closeModal();toast('User access updated.');location.reload();});};}
  $('#user-search').oninput=e=>{query=e.target.value;userPage=1;drawUsers();};$('#users-prev').onclick=()=>{userPage--;drawUsers();};$('#users-next').onclick=()=>{userPage++;drawUsers();};drawUsers();
  document.querySelectorAll('.policy-editor').forEach(form=>form.onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await rpc('admin_update_policy',{p_category:form.dataset.category,p_limit:Number(form.elements.limit.value),p_active:form.elements.active.checked});toast('Policy saved. New submissions use the updated limit.');});});
  expenseTable($('#admin-expenses'),rows,{showEmployee:true});
  function drawAudit(){const total=Math.max(1,Math.ceil(logs.length/10));$('#audit-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>ACTION</th><th>ACTOR</th><th>DETAILS</th><th>TIME</th></tr></thead><tbody>${logs.slice((auditPage-1)*10,auditPage*10).map(l=>`<tr><td>${h(l.action)}</td><td>${h(profiles.find(p=>p.id===l.actor_id)?.full_name||(l.actor_id?'Account':'System'))}</td><td>${l.expense_id?`<a href="expense-details.html?id=${l.expense_id}">${h(l.expense_id.slice(0,8))}</a>`:h(l.metadata.category||l.metadata.role||'Profile / access update')}</td><td>${timeLabel(l.created_at)}</td></tr>`).join('')}</tbody></table></div>`;$('#audit-page').textContent=`${logs.length} entries · Page ${auditPage} of ${total}`;$('#audit-prev').disabled=auditPage<=1;$('#audit-next').disabled=auditPage>=total;}
  $('#audit-prev').onclick=()=>{auditPage--;drawAudit();};$('#audit-next').onclick=()=>{auditPage++;drawAudit();};drawAudit();icons();
}

function roleRequests(profiles){
 const pending=profiles.filter(p=>p.role_request_status==='pending');
 return `<section class="panel section-space"><div class="panel-header"><div><h2>Role access requests <span class="category-pill">${pending.length}</span></h2><p>Only authorized administrators can grant manager or finance access.</p></div></div><div class="request-list">${pending.length?pending.map(p=>`<article class="request-row"><div><strong>${h(p.full_name)}</strong><p>${h(p.email)} · ${h(roleNames[p.requested_role])}</p><small class="muted-note">Requested ${timeLabel(p.role_requested_at)}</small></div><div class="request-actions"><button class="button secondary review-role-request" data-id="${p.id}" data-decision="rejected">Decline</button><button class="button primary review-role-request" data-id="${p.id}" data-decision="approved">Approve access</button></div></article>`).join(''):'<p class="muted-note">No role requests awaiting review.</p>'}</div></section>`;
}
